# Generated by new-portable-project.ps1.
# Edit the stage/TODO sections for your app; keep the upstream calls as-is.
param (
  [string]$PythonVersion = "__PYTHON_VERSION__",
  [string]$Workspace = "__WORKSPACE__",
  [string]$VCRuntimeDir = "",
  [switch]$SkipInstall
)

$ErrorActionPreference = "Stop"

$Root = Split-Path -Parent $PSScriptRoot
$Upstream = Join-Path $Root "__SUBMODULE_PATH__"
$UpstreamScripts = Join-Path $Upstream "scripts"
$Ws = if ([IO.Path]::IsPathRooted($Workspace)) { $Workspace } else { Join-Path $Root $Workspace }

if (-not (Test-Path (Join-Path $UpstreamScripts "bootstrap.ps1"))) {
  throw "Submodule missing at $Upstream. Run: git submodule update --init --recursive"
}

$AppDir = Join-Path $Root "__APP_DIR__"
$Requirements = Join-Path $Root "__REQUIREMENTS__"
if (-not (Test-Path $AppDir)) { throw "App directory not found: $AppDir" }
if (-not (Test-Path $Requirements)) { throw "Requirements file not found: $Requirements" }

New-Item -ItemType Directory -Path $Ws -Force | Out-Null

# 1. Stage the application. The runtime always reads <workspace>/app.
$TargetApp = Join-Path $Ws "app"
if (Test-Path $TargetApp) { Remove-Item $TargetApp -Recurse -Force }
New-Item -ItemType Directory -Path $TargetApp -Force | Out-Null
# Copy the app directory, but never copy the workspace into itself. In the
# multi-app layout the workspace lives at <app>/.portable, so a plain
# recursive copy would nest the workspace forever.
$WsFull = [IO.Path]::GetFullPath($Ws).TrimEnd('\')
Get-ChildItem -LiteralPath $AppDir -Force | ForEach-Object {
  $ItemFull = $_.FullName.TrimEnd('\')
  if ($_.Name -eq '__pycache__') { return }
  if ($ItemFull -eq $WsFull -or $WsFull.StartsWith($ItemFull + '\', [StringComparison]::OrdinalIgnoreCase)) { return }
  Copy-Item -LiteralPath $_.FullName -Destination $TargetApp -Recurse -Force
}
Copy-Item $Requirements (Join-Path $Ws "requirements.txt") -Force

# Optional deployment files (config.ini, start.bat, ...).
$Packaging = Join-Path $Root "packaging"
if (Test-Path $Packaging) {
  Copy-Item (Join-Path $Packaging "*") $Ws -Recurse -Force
}

# 2. Install the pinned Python if needed.
$PythonExe = Join-Path $Ws "python\python.exe"
$NeedBootstrap = $true
if (Test-Path $PythonExe) {
  $Actual = (& $PythonExe -V).Trim() -replace '^Python\s+', ''
  $NeedBootstrap = $Actual -ne $PythonVersion
}
if ($NeedBootstrap) {
  $Checksums = Join-Path $Ws "checksums.psd1"
  if (-not (Test-Path $Checksums)) {
    & (Join-Path $UpstreamScripts "update_checksums.ps1") `
      -Workspace $Ws -ChecksumFile $Checksums `
      -Version $PythonVersion -Arch amd64 -SkipTclTk
    if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "update_checksums.ps1 failed" }
  }
  & (Join-Path $UpstreamScripts "bootstrap.ps1") `
    -Workspace $Ws -Engine embeddable -Version $PythonVersion `
    -ChecksumFile $Checksums -NonInteractive
  if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "bootstrap.ps1 failed" }
}

# 3. Install dependencies.
if (-not $SkipInstall) {
  & (Join-Path $UpstreamScripts "pip.ps1") -Workspace $Ws install -r (Join-Path $Ws "requirements.txt")
  if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "pip install failed" }
}

# 4. Optional native runtime DLLs (for MSVC-built extensions).
if ($VCRuntimeDir) {
  foreach ($Name in @("msvcp140.dll", "msvcp140_1.dll")) {
    $Source = Join-Path $VCRuntimeDir $Name
    if (Test-Path $Source) {
      Copy-Item $Source (Join-Path $Ws "python\$Name") -Force
    }
    else {
      Write-Host "[WARN] $Name not found in $VCRuntimeDir" -ForegroundColor Yellow
    }
  }
}

# TODO: add your import/startup smoke test here, for example:
# & $PythonExe -c "import my_app; print('ok')"
# if ($LASTEXITCODE -ne 0) { throw "smoke test failed" }

# 5. Record provenance and build the ZIP.
$Commit = (& git -C $Upstream rev-parse HEAD).Trim()
@(
  "repo=https://github.com/ra9fael/python-portable-win",
  "commit=$Commit",
  "python=$PythonVersion",
  "built=$((Get-Date).ToString('yyyy-MM-dd HH:mm'))"
) | Set-Content (Join-Path $Ws "UPSTREAM.txt") -Encoding ASCII

& (Join-Path $UpstreamScripts "build_release.ps1") -Workspace $Ws
if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "build_release.ps1 failed" }

Write-Host "`n[OK] Workspace: $Ws" -ForegroundColor Green
Write-Host "     ZIP:       $(Join-Path $Ws 'dist')" -ForegroundColor Green
